<!--
  "Woher kommt jeder Wert?" — the Kopffeld-Check report body (OBO-156).

  Mockup page 3. Left is what the page said, right is what the screen shows,
  between them whoever changed it. The field that travelled furthest gets its
  own card on top, with the substring the lookup actually matched marked
  inside the value shown — the one sentence a reader needs to see why
  "1001" became "06O051001".

  Every fact comes from the payload. A key the server did not send renders as
  its fallback (the field's name, the old counters, no date) — never as an
  invented value. Shared by the dialog and the printable page.
-->
<template>
  <div class="hfc-report flex flex-col gap-4 text-sm text-foreground">
    <header class="flex flex-col gap-1">
      <div class="text-xs font-semibold tracking-wide text-primary">DocBits</div>
      <h2 class="text-lg font-semibold">{{ $t('header_field_check_report_title') }}</h2>
      <p class="text-muted-foreground">{{ $t('header_field_check_report_subtitle') }}</p>
      <router-link
        data-test="hfc-help-link"
        :to="helpRoute"
        target="_blank"
        class="inline-flex w-fit items-center gap-1 text-xs text-primary underline-offset-2 hover:underline print:hidden"
      >
        <Icon icon="mdi:help-circle-outline" class="size-4" />
        {{ $t('header_field_check_help_link') }}
      </router-link>
      <p v-if="metaLine" class="text-xs text-muted-foreground">{{ metaLine }}</p>
    </header>

    <div class="grid grid-cols-1 gap-3 sm:grid-cols-3">
      <div
        v-for="tile in tiles"
        :key="tile.key"
        data-test="hfc-tile"
        class="rounded-md border p-4"
        :class="tile.tone"
      >
        <div class="text-2xl font-semibold leading-tight">{{ tile.count }}</div>
        <div class="mt-1 text-xs">{{ $t(tile.key) }}</div>
      </div>
    </div>

    <p class="text-xs text-muted-foreground">{{ $t('header_field_check_row_length_hint') }}</p>

    <section
      v-if="hero"
      data-test="hfc-hero"
      class="rounded-md border-2 border-destructive/60 bg-destructive/5 p-4"
    >
      <div class="flex items-start justify-between gap-3">
        <div class="font-semibold">{{ entryLabel(hero) }}</div>
        <div class="text-xs font-semibold text-destructive">
          {{ $t('header_field_check_hero_verdict') }}
        </div>
      </div>

      <div class="mt-3 flex flex-wrap items-center gap-2">
        <div class="rounded border border-border bg-card px-3 py-2">
          <div class="text-[10px] uppercase tracking-wide text-muted-foreground">
            {{ $t('header_field_check_hero_on_document') }}
          </div>
          <div class="font-mono">{{ displayValue(hero, hero.document_value) || '—' }}</div>
        </div>

        <template v-if="heroTransform">
          <span class="flex items-center gap-1">
            <Icon icon="mdi:arrow-right" class="size-4 text-muted-foreground" />
            <span class="rounded border border-warning/40 bg-warning/10 px-2 py-0.5 text-xs">
              {{ transformChipText(heroTransform) }}
            </span>
          </span>
          <div
            v-if="heroTransform.directional"
            class="rounded border border-warning/40 bg-warning/5 px-3 py-2"
          >
            <div class="text-[10px] uppercase tracking-wide text-muted-foreground">
              {{ $t('header_field_check_hero_after') }}
            </div>
            <div class="font-mono">{{ displayValue(hero, heroTransform.to) }}</div>
          </div>
        </template>

        <span v-if="heroLookup" class="flex flex-wrap items-center gap-1">
          <Icon icon="mdi:arrow-right" class="size-4 text-muted-foreground" />
          <span
            v-for="(text, index) in lookupChipTexts(heroLookup)"
            :key="index"
            class="rounded border border-destructive/40 bg-destructive/10 px-2 py-0.5 text-xs"
          >
            {{ text }}
          </span>
        </span>
        <Icon v-else icon="mdi:arrow-right" class="size-4 text-muted-foreground" />

        <div class="rounded border-2 border-destructive/60 bg-card px-3 py-2">
          <div class="text-[10px] uppercase tracking-wide text-muted-foreground">
            {{ $t('header_field_check_hero_shown') }}
          </div>
          <div class="font-mono font-semibold">
            <template v-for="(part, index) in heroValueParts" :key="index">
              <mark v-if="part.hit" class="hfc-hl">{{ part.text }}</mark>
              <span v-else>{{ part.text }}</span>
            </template>
            <span v-if="!heroValueParts.length">—</span>
          </div>
        </div>
      </div>

      <p v-if="heroExplanation" class="mt-3 text-destructive">
        {{ heroExplanation }}
        <span v-if="heroSingleHit">{{ $t('header_field_check_hero_single_hit') }}</span>
      </p>

      <p v-if="heroDrives.length" class="mt-3 border-t border-destructive/30 pt-3">
        <span class="font-semibold">
          {{ $t('header_field_check_hero_drives', { count: heroDrives.length }) }}
        </span>
        <span v-for="(dependant, index) in heroDrives" :key="dependant.name">
          {{ dependant.label }}
          <strong v-if="dependant.value">{{ dependant.value }}</strong
          >{{ index < heroDrives.length - 1 ? ',' : '' }}
        </span>
      </p>
      <p v-if="heroContrast" data-test="hfc-hero-contrast" class="mt-1 text-destructive">
        {{ $t('header_field_check_hero_document_said', heroContrast) }}
      </p>
    </section>

    <div class="flex flex-col">
      <div
        v-for="entry in rows"
        :key="entry.name"
        data-test="hfc-row"
        class="grid items-center gap-3 border-b border-border px-2 py-3 hfc-row"
        :class="rowClass(entry)"
      >
        <div class="font-semibold">{{ entryLabel(entry) }}</div>

        <div class="font-mono">
          <template v-if="entry.document_value">{{ displayValue(entry, entry.document_value) }}</template>
          <!-- A required field nothing filled: the status chip already says
               "Required field"; "not on the document" would be a claim about
               the page nobody checked. -->
          <span v-else-if="isRequiredEmpty(entry)" class="text-muted-foreground">—</span>
          <span v-else-if="entry.document_value_known" class="text-muted-foreground">
            — {{ $t('header_field_check_not_on_document') }}
          </span>
          <span v-else class="text-muted-foreground">
            {{ $t('header_field_check_origin_unrecorded') }}
          </span>
        </div>

        <div class="flex flex-wrap gap-1">
          <span
            v-for="(chip, index) in rowChips(entry)"
            :key="index"
            class="rounded border px-2 py-0.5 text-xs"
            :class="chip.cls"
          >
            {{ chip.text }}
          </span>
        </div>

        <Icon icon="mdi:arrow-right" class="size-4 text-muted-foreground" />

        <div class="font-mono font-semibold">
          <template v-if="entry.current_value">{{ displayValue(entry, entry.current_value) }}</template>
          <span v-else class="font-normal text-muted-foreground">
            {{ $t('header_field_check_value_empty') }}
          </span>
        </div>

        <div class="text-right">
          <span class="rounded border px-2 py-0.5 text-xs" :class="statusChipClass(entry)">
            {{ $t(statusChipKey(entry, report.fields)) }}
          </span>
        </div>
      </div>
    </div>

    <p class="text-xs text-muted-foreground">
      {{
        $t('header_field_check_summary_sentence', {
          hidden: hiddenUnchanged,
          empty: report.summary?.empty_count ?? 0,
          required: report.summary?.required_empty_count ?? 0,
        })
      }}
    </p>

    <div class="flex flex-wrap items-center gap-4 rounded-md border border-border bg-muted p-3 text-xs">
      <span class="font-semibold uppercase tracking-wide text-muted-foreground">
        {{ $t('header_field_check_legend') }}
      </span>
      <span class="flex items-center gap-1">
        <span class="inline-block size-3 rounded-sm border border-success/40 bg-success/10" />
        {{ $t('header_field_check_legend_unchanged') }}
      </span>
      <span class="flex items-center gap-1">
        <span class="inline-block size-3 rounded-sm border border-warning/40 bg-warning/10" />
        {{ $t('header_field_check_legend_changed') }}
      </span>
      <span class="flex items-center gap-1">
        <span class="inline-block size-3 rounded-sm border border-destructive/40 bg-destructive/10" />
        {{ $t('header_field_check_legend_not_on_document') }}
      </span>
    </div>

    <footer class="flex flex-wrap justify-between gap-2 border-t border-border pt-3 text-xs text-muted-foreground">
      <span>{{ $t('header_field_check_footer_readonly') }}</span>
      <span>{{ $t('header_field_check_footer_document', { id: report.document?.id }) }}</span>
    </footer>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { storeToRefs } from 'pinia';
import { Icon } from '@iconify/vue';
import type {
  HeaderFieldEntry,
  HeaderFieldReport,
  HeaderFieldStep,
} from 'src/types/headerFieldReport';
import {
  changingSteps,
  datasetLabel,
  docTypeLabel,
  entryLabel,
  formatHeaderValue,
  heroDocumentContrast,
  heroField,
  highlightParts,
  rowFields,
  rowTone,
  sourceTone,
  statusChipKey,
  stepKind,
  stepLabelKey,
  SOURCE_TONE_CLASSES,
  type HighlightPart,
} from 'src/utils/header-field-check-view';
import { HEADER_FIELD_CHECK_HELP_ROUTE } from 'src/router/header-field-check-routes';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';
import dateUtils from 'src/utils/date';
import docTypeLable from 'src/utils/docTypeLable';

/** The app's own date display: the user's "Date Pattern" preference. */
function formatUserDate(iso: string): string {
  return dateUtils.methods.formatDateAccordingToPreference(iso, true, iso);
}

export default defineComponent({
  name: 'HeaderFieldReportView',
  components: { Icon },
  props: {
    report: { type: Object as PropType<HeaderFieldReport>, required: true },
    /**
     * The fields configured as a date. The payload does not carry a field
     * type; the validation screen knows it and passes it down. Their values
     * are shown in the user's date format instead of the stored ISO string.
     */
    dateFields: { type: Array as PropType<string[]>, default: () => [] },
  },
  setup() {
    // The organisation's document types, as the validation screen's type
    // dropdown lists them — the label the reader knows the document by.
    const { doc_types_sub_types_list: docTypes } = storeToRefs(useDropdownStore());
    return { docTypes };
  },
  computed: {
    /** The explanation page "Woher die Daten kommen" (mockup page 4). */
    helpRoute(): { name: string } {
      return { name: HEADER_FIELD_CHECK_HELP_ROUTE };
    },
    metaLine(): string {
      const doc = this.report.document ?? ({} as HeaderFieldReport['document']);
      const type = docTypeLabel(doc.doc_type, this.docTypes, (value) =>
        docTypeLable.methods.displayDocType(value),
      );
      return [doc.filename, type, formatHeaderValue(doc.date, true, formatUserDate)]
        .filter((part): part is string => typeof part === 'string' && part !== '')
        .join(' · ');
    },
    tiles(): Array<{ key: string; count: number; tone: string }> {
      const s = this.report.summary ?? ({} as HeaderFieldReport['summary']);
      return [
        {
          key: 'header_field_check_tile_unchanged',
          count: s.unchanged_count ?? 0,
          tone: 'border-success/40 bg-success/5',
        },
        {
          key: 'header_field_check_tile_changed',
          count: s.changed_on_way_count ?? s.changed_count ?? 0,
          tone: 'border-warning/40 bg-warning/5',
        },
        {
          key: 'header_field_check_tile_not_on_document',
          count: s.not_on_document_count ?? s.partial_match_count ?? 0,
          tone: 'border-destructive/40 bg-destructive/5',
        },
      ];
    },
    hero(): HeaderFieldEntry | null {
      return heroField(this.report);
    },
    heroTransform(): HeaderFieldStep | null {
      return this.hero?.chain?.find((step) => step.stage === 'transform') ?? null;
    },
    heroLookup(): HeaderFieldStep | null {
      return this.hero?.chain?.find((step) => step.stage === 'lookup') ?? null;
    },
    heroValueParts(): HighlightPart[] {
      if (!this.hero) return [];
      // A date is shown in the user's format; the lookup's span points into
      // the stored string, so a reformatted date is shown unmarked.
      if (this.isDateField(this.hero)) {
        const text = this.displayValue(this.hero, this.hero.current_value);
        return text ? [{ text, hit: false }] : [];
      }
      return highlightParts(this.hero.current_value, this.heroLookup?.match_span);
    },
    heroExplanation(): string {
      const lookup = this.heroLookup;
      if (!this.hero || !lookup || lookup.match_quality !== 'partial' || !lookup.from) {
        return '';
      }
      return this.$t('header_field_check_hero_partial_explain', {
        needle: lookup.from,
        value: this.hero.current_value,
      });
    },
    heroSingleHit(): boolean {
      return this.heroLookup?.candidate_count === 1;
    },
    heroDrives(): Array<{ name: string; label: string; value: string }> {
      const hero = this.hero;
      if (!hero?.drives?.length) return [];
      const byName = new Map<string, HeaderFieldEntry>(
        (this.report.fields ?? []).map(
          (field): [string, HeaderFieldEntry] => [field.name, field],
        ),
      );
      return hero.drives.map((name) => ({
        name,
        label: entryLabel(byName.get(name)) || name,
        value: this.displayValue(byName.get(name), hero.drives_values?.[name] ?? ''),
      }));
    },
    /** "On the document it said …" for the first filled field that disagrees. */
    heroContrast(): { label: string; value: string } | null {
      const contrast = heroDocumentContrast(this.report);
      if (!contrast) return null;
      const field = (this.report.fields ?? []).find((entry) => entry.name === contrast.name);
      return { label: contrast.label, value: this.displayValue(field, contrast.value) };
    },
    rowResult(): { rows: HeaderFieldEntry[]; hiddenUnchanged: number } {
      return rowFields(this.report);
    },
    rows(): HeaderFieldEntry[] {
      return this.rowResult.rows;
    },
    hiddenUnchanged(): number {
      return this.rowResult.hiddenUnchanged;
    },
  },
  methods: {
    entryLabel,
    statusChipKey,
    isDateField(entry: HeaderFieldEntry | null | undefined): boolean {
      return !!entry && this.dateFields.includes(entry.name);
    },
    /** A value as the user sees it: a date field in the user's date format. */
    displayValue(entry: HeaderFieldEntry | null | undefined, value: string | null | undefined): string {
      return formatHeaderValue(value, this.isDateField(entry), formatUserDate);
    },
    isRequiredEmpty(entry: HeaderFieldEntry): boolean {
      return !entry.current_value && entry.is_required === true;
    },
    stepText(step: HeaderFieldStep): string {
      const key = stepLabelKey(step);
      return key ? this.$t(key) : '';
    },
    transformChipText(step: HeaderFieldStep): string {
      if (step.script?.label) {
        return this.$t('header_field_check_step_script_named', { name: step.script.label });
      }
      return this.stepText(step);
    },
    /**
     * The chips of a lookup: which record it read ("Bestellungen: 06O051001")
     * and, for anything short of an exact hit, how well it matched — the
     * record must not swallow the one fact that matters.
     */
    lookupChipTexts(step: HeaderFieldStep): string[] {
      const quality = this.stepText(step);
      if (!step.dataset) return quality ? [quality] : [];
      const dataset = datasetLabel(step.dataset, (key) => this.$t(key));
      const record = step.to
        ? this.$t('header_field_check_step_lookup_record', { dataset, value: step.to })
        : this.$t('header_field_check_step_lookup_from', { dataset });
      return step.match_quality === 'exact' || !quality ? [record] : [record, quality];
    },
    rowChips(entry: HeaderFieldEntry): Array<{ text: string; cls: string }> {
      return changingSteps(entry).flatMap((step) => {
        const cls = this.chipClass(step);
        if (step.stage === 'lookup') {
          return this.lookupChipTexts(step).map((text) => ({ text, cls }));
        }
        const text = step.stage === 'transform' ? this.transformChipText(step) : this.stepText(step);
        return text ? [{ text, cls }] : [];
      });
    },
    chipClass(step: HeaderFieldStep): string {
      const kind = stepKind(step);
      if (kind === 'bad') return 'border-destructive/40 bg-destructive/10';
      if (kind === 'warn') return 'border-warning/40 bg-warning/10';
      if (kind === 'lookup') return 'border-success/40 bg-success/10';
      return SOURCE_TONE_CLASSES[sourceTone(step.source)];
    },
    rowClass(entry: HeaderFieldEntry): string {
      const tone = rowTone(entry);
      if (tone === 'bad') return 'bg-destructive/5';
      if (tone === 'changed') return 'bg-warning/5';
      return '';
    },
    statusChipClass(entry: HeaderFieldEntry): string {
      const tone = rowTone(entry);
      if (tone === 'bad') return 'border-destructive/40 bg-destructive/10 text-destructive';
      if (tone === 'changed') return 'border-warning/40 bg-warning/10';
      return 'border-success/40 bg-success/10 text-success-badge-text';
    },
  },
});
</script>

<style lang="scss" scoped>
.hfc-row {
  /* The shown value takes the spare width, not the chips: a flexible chip
     column left a wide gap between the last chip and the arrow. */
  grid-template-columns: 180px 220px 220px 20px minmax(0, 1fr) 150px;
}

.hfc-hl {
  background: color-mix(in srgb, var(--destructive) 25%, transparent);
  color: inherit;
  border-radius: 2px;
  padding: 0 1px;
}

@media (max-width: 900px) {
  .hfc-row {
    grid-template-columns: 1fr;
  }
}
</style>
